def firstBracketError(s):
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, c in enumerate(s, 1):
        if c in '([{':
            stack.append((c, i))
        elif c in match:
            if not stack or stack[-1][0] != match[c]:
                return i
            stack.pop()
    return stack[0][1] if stack else 0
